def funded(sel: Selection, result: mathopt.SolveResult) -> list[str]:
    """The projects a solution funds, in portfolio order."""
    return [pid for pid, v in sel.x.items() if result.variable_values(v) > 0.5]

x = sel.x
count_program = {g: sum(x[i] for i in ids(small, program=g)) for g in PROGRAMS}
count_region = {r: sum(x[i] for i in ids(small, region=r)) for r in REGIONS}
capex = sum(p.capex * x[p.project_id] for p in small.projects)
crew = sum(p.crew_months * x[p.project_id] for p in small.projects)

tasks_of = {team: sum(x[w, t] for w in members for t in tasks) for team, members in TEAMS.items()}
if team_max is not None:
    for team, count in tasks_of.items():
        model.add_linear_constraint(count <= team_max, name=f"cap_{team.replace(' ', '')}")

